'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var incrnanmeanabs2 = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanmeanabs2, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.strictEqual( typeof incrnanmeanabs2(), 'function', 'returns expected value' );
	t.end();
});

tape( 'the initial accumulated value is `null`', function test( t ) {
	var acc = incrnanmeanabs2();
	t.strictEqual( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'the accumulator function incrementally computes an arithmetic mean of squared absolute values', function test( t ) {
	var expected;
	var actual;
	var count;
	var data;
	var sum;
	var acc;
	var i;
	var d;
	var N;

	data = [ 2.0, -3.0, 2.0, NaN, -4.0, NaN, 3.0, -4.0 ];
	N = data.length;
	count = 0;
	sum = 0;

	acc = incrnanmeanabs2();

	for ( i = 0; i < N; i++ ) {
		d = data[ i ];
		if ( isnan( d ) === false ) {
			sum += d * d;
			count += 1;
		}
		expected = sum / count;
		actual = acc( d );
		t.strictEqual( isAlmostSameValue( actual, expected, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current mean', function test( t ) {
	var data;
	var acc;
	var i;

	data = [ 2.0, NaN, -3.0, NaN, -1.0 ];
	acc = incrnanmeanabs2();
	for ( i = 0; i < data.length; i++ ) {
		acc( data[ i ] );
	}
	t.strictEqual( acc(), 14.0/3.0, 'returns expected value' );
	t.end();
});
